seen = set(); stock = {"L001": 0}
msgs = [("m-101","L001",+25), ("m-102","L001",-1), ("m-102","L001",-1), ("m-103","L001",-2)]
for mid, lot, d in msgs:
    if mid in seen:
        print("건너뜀", mid); continue
    seen.add(mid); stock[lot] += d
print(stock)

TOOLS = {
    "lot_status": lambda lot: {"L002": "WT HOLD 10:10"}.get(lot, "없음"),
    "hold_reason": lambda lot: {"L002": "프로브 카드 접촉 불량 의심"}.get(lot, "없음"),
}
plan = [("lot_status", "L002"), ("hold_reason", "L002")]
for step, (tool, arg) in enumerate(plan, 1):
    obs = TOOLS[tool](arg)
    print(f"[{step}] 행동 {tool}({arg}) / 관찰 {obs}")
